  /* ── home ───────────────────────────────────────────────────────── */
  "home.ready": "Ready to lift.",
  "home.readyName": "Ready, {name}.",
  "home.weekLine": "Week {n} of your program · strength + muscle, tracked properly.",
  "home.rollingLine": "The last seven days, rolling · strength + muscle, tracked properly.",
  "home.start": "Start New Workout",
  "home.pinnedPresets": "Pinned presets",
  "home.pinnedTimers": "Pinned timers",
  "home.noPinnedPresets": "Nothing pinned yet. Open *Library → Presets* and tap {icon} on a bundle to keep it here.",
  "home.pinnedReorderHint": "Drag {icon} to set the order your pinned bundles sit in here. The rest of your presets stay where they are.",
